function AIWrite() {
  return (
    <div style={{ padding: "15px" }}>
      <h3 style={{ color: "#4CAF50" }}>AI 독후감 생성</h3>

      <textarea
        placeholder="책 구절이나 느낌을 입력하세요"
        style={{
          width: "100%",
          height: "150px",
          borderRadius: "10px",
          padding: "10px"
        }}
      />

      <button style={btn}>
        AI 생성하기
      </button>

      <div style={{
        marginTop: "20px",
        background: "white",
        padding: "15px",
        borderRadius: "10px"
      }}>
        생성된 독후감이 여기에 표시됩니다
      </div>
    </div>
  );
}

const btn = {
  marginTop: "10px",
  width: "100%",
  padding: "12px",
  background: "#7ED957",
  color: "white",
  border: "none",
  borderRadius: "10px",
  fontWeight: "bold"
};

export default AIWrite;
